SELECT

FROM finance_transaction
WHERE 1=1

    AND project_id = #{param.projectId}


    AND transaction_no LIKE CONCAT('%', #{param.transactionNo}, '%')


    AND transaction_type = #{param.transactionType}


    AND transaction_category = #{param.transactionCategory}


    AND transaction_status = #{param.transactionStatus}


    AND approval_status = #{param.approvalStatus}


    AND payment_method = #{param.paymentMethod}


    AND bank_name LIKE CONCAT('%', #{param.bankName}, '%')


    AND account_subject LIKE CONCAT('%', #{param.accountSubject}, '%')


    AND manager_id = #{param.managerId}


    AND manager_name LIKE CONCAT('%', #{param.managerName}, '%')


    AND approver_id = #{param.approverId}


    AND approver_name LIKE CONCAT('%', #{param.approverName}, '%')


    AND amount >= #{param.minAmount}


    AND amount <= #{param.maxAmount}


    AND transaction_date >= #{param.transactionStartDate}


    AND transaction_date <= #{param.transactionEndDate}


    AND approval_date >= #{param.approvalStartDate}


    AND approval_date <= #{param.approvalEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (transaction_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR description LIKE CONCAT('%', #{param.keyword}, '%')
         OR bank_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR manager_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

